from fractions import Fraction
from typing import Dict, Tuple

HodgeDiamond = Tuple[int, Dict[Tuple[int, int], int]]


def epoly(diamond: HodgeDiamond, u: Fraction, v: Fraction) -> Fraction:
    """E(X; u, v) = sum_{p,q=0..n} (-1)^(p+q) h^{p,q} u^p v^q."""
    n, h = diamond
    total = Fraction(0)
    for p in range(n + 1):
        for q in range(n + 1):
            sign = -1 if (p + q) % 2 else 1
            total += sign * h.get((p, q), 0) * (u ** p) * (v ** q)
    return total


def euler_char(diamond: HodgeDiamond) -> int:
    n, h = diamond
    return sum((-1 if (p + q) % 2 else 1) * h.get((p, q), 0)
               for p in range(n + 1) for q in range(n + 1))


if __name__ == "__main__":
    k3: HodgeDiamond = (2, {(0, 0): 1, (2, 0): 1, (0, 2): 1, (2, 2): 1, (1, 1): 20})
    # E(K3; u, v) = 1 + u^2 + v^2 + u^2 v^2 + 20 u v
    print("E(K3; 2, 3) =", epoly(k3, Fraction(2), Fraction(3)))
    print("E(K3; 1, 1) =", epoly(k3, Fraction(1), Fraction(1)), " chi =", euler_char(k3))

from fractions import Fraction
from typing import Dict, Tuple

HodgeDiamond = Tuple[int, Dict[Tuple[int, int], int]]


def h_of(d: HodgeDiamond, p: int, q: int) -> int:
    return d[1].get((p, q), 0)


def mirror(d: HodgeDiamond) -> HodgeDiamond:
    n = d[0]
    return (n, {(p, q): h_of(d, n - p, q)
                for p in range(n + 1) for q in range(n + 1)
                if h_of(d, n - p, q) != 0})


def epoly(d: HodgeDiamond, u: Fraction, v: Fraction) -> Fraction:
    n = d[0]
    return sum((-1 if (p + q) % 2 else 1) * h_of(d, p, q) * u ** p * v ** q
               for p in range(n + 1) for q in range(n + 1))


def verify_mirror_equation(d: HodgeDiamond, u: Fraction, v: Fraction) -> bool:
    """E(X^; u, v) == (-1)^n u^n E(X; 1/u, v)."""
    n = d[0]
    lhs = epoly(mirror(d), u, v)
    rhs = ((-1) ** n) * (u ** n) * epoly(d, 1 / u, v)
    return lhs == rhs


if __name__ == "__main__":
    quintic: HodgeDiamond = (3, {
        (0, 0): 1, (3, 3): 1, (0, 3): 1, (3, 0): 1,
        (1, 1): 1, (2, 2): 1, (2, 1): 101, (1, 2): 101})
    print("mirror equation holds at (5, -7):",
          verify_mirror_equation(quintic, Fraction(5), Fraction(-7)))
    print("chi(quintic)        =", epoly(quintic, Fraction(1), Fraction(1)))
    print("chi(mirror quintic) =", epoly(mirror(quintic), Fraction(1), Fraction(1)))

