function MIRROR(n, h):
    hm <- empty table
    for p in 0..n:
        for q in 0..n:
            hm[p][q] <- h[n - p][q]
    return (n, hm)

function SIGN_LAW(n, h):
    chi   <- sum_{p,q} (-1)^(p+q) h[p][q]
    hm    <- MIRROR(n, h)
    chi_m <- sum_{p,q} (-1)^(p+q) hm[p][q]
    assert chi_m == (-1)^n * chi
    return chi, chi_m

